package com.crm.invoice.repository;import com.crm.invoice.entity.ReminderTask;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import org.springframework.data.domain.*;import java.time.LocalDate;import java.util.Optional;
public interface ReminderTaskRepository extends JpaRepository<ReminderTask,Long>{@Modifying @Query("update ReminderTask t set t.state='CANCELLED',t.outcome='Policy changed' where t.state='PREPARED'") void cancelForPolicyChange();boolean existsByInvoiceIdAndPolicyRevisionAndScheduledFor(Long invoice,long revision,LocalDate day);@Query("select t from ReminderTask t where (:state is null or t.state=:state)") Page<ReminderTask> list(@Param("state") String state,Pageable page);@Modifying @Query("update ReminderTask t set t.state='CANCELLED',t.outcome='Invoice no longer eligible' where t.invoiceId=:id and t.state='PREPARED'") void cancelForInvoice(@Param("id") Long id);}
